INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111'), 1, 'Ask who decides an `arn` or an `id`: you in the configuration, or the cloud provider when the object is created?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111'), 2, 'Run the plan in your head with `-input=false`, as CI does: where could a value for a variable with no default come from?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111'), 3, 'Terraform''s state maps each resource address (`aws_s3_bucket.uploads`) to one real object. What does a new address look like to it?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111'), 'The first plan for the uploads bucket shows:

```text
  # aws_s3_bucket.uploads will be created
  + resource "aws_s3_bucket" "uploads" {
      + arn                         = (known after apply)
      + bucket                      = "rice-rocket-staging-uploads"
      + bucket_domain_name          = (known after apply)
      + id                          = (known after apply)
      + tags                        = {
          + "Environment" = "staging"
          + "Project"     = "rice-rocket"
        }
    }

Plan: 1 to add, 0 to change, 0 to destroy.
```

Statement: "`arn` and `id` are set by AWS when the bucket is created, so the plan cannot know them yet; any value built from them is also `(known after apply)`."', 'single_choice'::question_type, 'True. Attributes you set (`bucket`, `tags`) are known at plan time. Computed attributes are filled in by the provider from the API''s answer after the object exists, so the plan shows `(known after apply)`. An expression that uses them, like `aws_s3_bucket.uploads.arn` in an output or another resource, is unknown in the same plan. The misconception is that a plan has asked AWS for those values.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111'), 'The CI job runs the plan without a value for `env`:

```hcl
variable "env" {
  type = string
}
```

```text
$ terraform plan -input=false
```

Statement: "Terraform treats a variable with no default and no value as an empty string, so the plan names the bucket `rice-rocket--uploads` and carries on."', 'single_choice'::question_type, 'False. A variable without a default is required. Interactively Terraform asks for it; with `-input=false` (as in CI) the plan stops with an error saying no value was given for the required variable `env`. Values come from `-var`, `-var-file`, `*.auto.tfvars` files or `TF_VAR_env`. The misconception is that missing variables default to empty, which would silently create wrongly named resources.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111'), 'A teammate renamed the resource label to read better and planned again:

```diff
- resource "aws_s3_bucket" "uploads" {
+ resource "aws_s3_bucket" "user_uploads" {
    bucket = "rice-rocket-staging-uploads"
  }
```

```text
  # aws_s3_bucket.uploads will be destroyed
  # aws_s3_bucket.user_uploads will be created
Plan: 1 to add, 0 to change, 1 to destroy.
```

Statement: "State maps each resource address to one real object, so a renamed label looks like a new resource and the old one gets destroyed, unless a `moved` block says the two addresses are the same object."', 'single_choice'::question_type, 'True. Terraform does not compare bucket names to guess that two resources are the same: state stores `aws_s3_bucket.uploads` -> the real bucket, and `aws_s3_bucket.user_uploads` has no entry, so it plans a create and a destroy (which would fail anyway on a bucket that still holds objects, or worse succeed on an empty one). A `moved { from = aws_s3_bucket.uploads  to = aws_s3_bucket.user_uploads }` block turns the change into a rename in state; lesson 5 covers it. Resource labels are part of the identity, not cosmetics.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_111') AND order_index = 3)
    RETURNING id
)
