INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_tf_112', (SELECT id FROM catalog.course WHERE public_id = 'terraform-infra-as-code'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'terraform-infra-as-code') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-tf-1-1' AND is_deleted = false LIMIT 1), 'uploads-bucket-and-logs', 'Describe the uploads bucket and the api logs', 'Until now Rice Rocket''s uploads bucket and the api''s log group were clicked together in the AWS console, once per environment, with small differences nobody could explain. The editor holds `infra/main.tf` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: `env` accepts only `staging` or `production` (error message `env must be staging or production.`); every name starts with `rice-rocket-<env>` and every resource that takes tags gets `Project`, `Environment` and `ManagedBy`; the bucket `rice-rocket-<env>-uploads` keeps old versions and blocks public access; the versioning and public access settings follow whichever bucket the environment creates; the api log group `/rice-rocket-<env>/api` keeps logs 30 days in production and 7 elsewhere; and the outputs give the bucket''s name and ARN. Run plans the file for staging and production with a plan simulator.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
