INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 1, 'Plan it for two environments in your head: which values must change with `env`, and which resources must point at the bucket instead of at its name written out?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 2, 'Look at a `validation` block inside `variable`, a `locals` block, string templates `"${local.name}-uploads"`, references like `aws_s3_bucket.uploads.id`, a conditional `a ? b : c`, and `output` blocks.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 3, 'A queue per environment with a dead-letter queue looks like: `locals { name = "shop-${var.stage}" }`, `resource "aws_sqs_queue" "dlq" { name = "${local.name}-dlq" }`, `resource "aws_sqs_queue" "jobs" { name = "${local.name}-jobs"  message_retention_seconds = var.stage == "prod" ? 1209600 : 345600  redrive_policy = jsonencode({ deadLetterTargetArn = aws_sqs_queue.dlq.arn, maxReceiveCount = 5 }) }`, and `output "jobs_url" { value = aws_sqs_queue.jobs.url }`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"env-variable","label":"The environment name, refused unless it is a known one","code":"variable \"env\" {\n  type        = string\n  description = \"Environment name: staging or production.\"\n  validation {\n    condition     = contains([\"staging\", \"production\"], var.env)\n    error_message = \"env must be staging or production.\"\n  }\n}"},{"id":"name-and-tags","label":"One name prefix and one tag set for every resource","code":"locals {\n  name = \"rice-rocket-${var.env}\"\n  tags = {\n    Project     = \"rice-rocket\"\n    Environment = var.env\n    ManagedBy   = \"terraform\"\n  }\n}"},{"id":"uploads-bucket","label":"The uploads bucket, named per environment","code":"resource \"aws_s3_bucket\" \"uploads\" {\n  bucket = \"${local.name}-uploads\"\n  tags   = local.tags\n}"},{"id":"uploads-versioning","label":"Keep old versions of every uploaded object","code":"resource \"aws_s3_bucket_versioning\" \"uploads\" {\n  bucket = aws_s3_bucket.uploads.id\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}"},{"id":"api-log-group","label":"api logs, kept longer in production","code":"resource \"aws_cloudwatch_log_group\" \"api\" {\n  name              = \"/${local.name}/api\"\n  retention_in_days = var.env == \"production\" ? 30 : 7\n  tags              = local.tags\n}"},{"id":"outputs","label":"What the api deployment needs to know","code":"output \"uploads_bucket\" {\n  value = aws_s3_bucket.uploads.bucket\n}\n\noutput \"uploads_bucket_arn\" {\n  value = aws_s3_bucket.uploads.arn\n}"},{"id":"env-variable-no-validation","label":"The environment name, refused unless it is a known one","code":"variable \"env\" {\n  type        = string\n  description = \"Environment name: staging or production.\"\n  default     = \"staging\"\n}","distractor":true},{"id":"uploads-bucket-shared-name","label":"The uploads bucket, named per environment","code":"resource \"aws_s3_bucket\" \"uploads\" {\n  bucket = \"rice-rocket-uploads\"\n  tags   = local.tags\n}","distractor":true},{"id":"versioning-hardcoded-bucket","label":"Keep old versions of every uploaded object","code":"resource \"aws_s3_bucket_versioning\" \"uploads\" {\n  bucket = \"rice-rocket-staging-uploads\"\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
