VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 'A staging plan creates the bucket, its two settings and the log group', '{"checks":["parse","plan","actions"],"vars":{"env":"staging"}}', '{"parse":"ok","plan":"Plan: 4 to add, 0 to change, 0 to destroy.","actions":{"aws_cloudwatch_log_group.api":"create","aws_s3_bucket.uploads":"create","aws_s3_bucket_public_access_block.uploads":"create","aws_s3_bucket_versioning.uploads":"create"}}', 4, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 'Staging: names, versioning, public access, 7-day logs and tags', '{"checks":["names","settings"],"vars":{"env":"staging"}}', '{"names":{"bucket":"rice-rocket-staging-uploads","versioning":"follows the bucket","publicAccessBlock":"follows the bucket","logGroup":"/rice-rocket-staging/api"},"settings":{"versioning":"Enabled","publicBlocked":true,"logRetentionDays":7,"tags":{"Project":"rice-rocket","Environment":"staging","ManagedBy":"terraform"}}}', 4, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 'An unknown environment name is refused before anything is planned', '{"checks":["plan"],"vars":{"env":"prod"}}', '{"plan":"Error: Invalid value for variable: var.env: env must be staging or production."}', 4, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 'Production gets its own bucket, settings that follow it and 30-day logs', '{"checks":["names","settings"],"vars":{"env":"production"}}', '{"names":{"bucket":"rice-rocket-production-uploads","versioning":"follows the bucket","publicAccessBlock":"follows the bucket","logGroup":"/rice-rocket-production/api"},"settings":{"versioning":"Enabled","publicBlocked":true,"logRetentionDays":30,"tags":{"Project":"rice-rocket","Environment":"production","ManagedBy":"terraform"}}}', 4, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_112'), 'Planned again over the staging state: no changes, and the outputs name the bucket', '{"checks":["plan","outputs"],"vars":{"env":"staging"},"state":{"aws_s3_bucket.uploads":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-staging-uploads","tags":{"Project":"rice-rocket","Environment":"staging","ManagedBy":"terraform"},"id":"rice-rocket-staging-uploads","arn":"arn:aws:s3:::rice-rocket-staging-uploads"}},"aws_s3_bucket_versioning.uploads":{"type":"aws_s3_bucket_versioning","attrs":{"bucket":"rice-rocket-staging-uploads","versioning_configuration":[{"status":"Enabled"}],"id":"rice-rocket-staging-uploads"}},"aws_s3_bucket_public_access_block.uploads":{"type":"aws_s3_bucket_public_access_block","attrs":{"bucket":"rice-rocket-staging-uploads","block_public_acls":true,"block_public_policy":true,"ignore_public_acls":true,"restrict_public_buckets":true,"id":"rice-rocket-staging-uploads"}},"aws_cloudwatch_log_group.api":{"type":"aws_cloudwatch_log_group","attrs":{"name":"/rice-rocket-staging/api","retention_in_days":7,"tags":{"Project":"rice-rocket","Environment":"staging","ManagedBy":"terraform"},"id":"/rice-rocket-staging/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-staging/api"}}}}', '{"plan":"No changes. Your infrastructure matches the configuration.","outputs":{"uploads_bucket":"rice-rocket-staging-uploads","uploads_bucket_arn":"arn:aws:s3:::rice-rocket-staging-uploads"}}', 4, false, true, 5);
