INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121'), 1, 'Read the symbol in front of the resource and the comment at the end of the changed line. What does `-/+` do to the object that exists today?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121'), 2, 'A plan line `~ a = 32 -> 20` is a call Terraform will make to the cloud API. Who made the value 32 in the first place?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121'), 3, 'Compare `terraform apply` with `terraform apply tfplan`: which one plans again, and what does Terraform do with a saved plan when the state moved on?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121'), 'A pull request titled "rename the database to our naming convention" produced this plan:

```text
  # aws_db_instance.main must be replaced
-/+ resource "aws_db_instance" "main" {
      ~ address    = "rr-staging-db.c9x2k1.ap-southeast-1.rds.amazonaws.com" -> (known after apply)
      ~ id         = "db-STAGING7Q2" -> (known after apply)
      ~ identifier = "rr-staging-db" -> "rice-rocket-staging" # forces replacement
        # (11 unchanged attributes hidden)
    }

Plan: 1 to add, 0 to change, 1 to destroy.
```

Statement: "Only the name changes, so AWS renames the instance in place and keeps the data; `-/+` here is cosmetic."', 'single_choice'::question_type, 'False. `-/+` means destroy the existing object, then create a new one, and `# forces replacement` names the attribute that causes it: the provider cannot change `identifier` through an update, so the plan deletes the database and creates an empty one. The `1 to destroy` in the summary is the line to stop at. A replaced database is a new, empty database (or one restored from a snapshot, by hand). The misconception is reading the attribute that changed instead of the action.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
