FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121'), 'RDS storage autoscaling grew the disk last month. Every plan since shows:

```text
  # aws_db_instance.main will be updated in-place
  ~ resource "aws_db_instance" "main" {
      ~ allocated_storage = 32 -> 20
        id                = "db-PRODUCTION7Q2"
        # (14 unchanged attributes hidden)
    }

Plan: 0 to add, 1 to change, 0 to destroy.
```

Statement: "Applying this is harmless: Terraform only writes 20 back into its state file and leaves the real storage alone."', 'single_choice'::question_type, 'False. An update in a plan is an API call: Terraform would ask RDS to set the storage to 20 GiB, which RDS refuses because allocated storage can only grow, so the apply fails (and keeps failing on every run). The value is managed outside Terraform on purpose, so the configuration should say so with `lifecycle { ignore_changes = [allocated_storage] }`. The misconception is that a plan only edits state: state is updated after the real change succeeds.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121') AND order_index = 2)
    RETURNING id
)
