        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121'), 'The release job saves the reviewed plan and applies exactly that file:

```text
$ terraform plan -out tfplan        # reviewed in the pull request
$ terraform apply tfplan            # run after approval
```

Statement: "`terraform apply tfplan` performs the saved actions without planning again, and if the state changed after the plan was made, Terraform refuses the stale plan instead of applying it."', 'single_choice'::question_type, 'True. A saved plan records the actions and the state it was made against. Applying it does not refresh or re-plan, so what runs is what was reviewed. If another apply changed the state in between, Terraform reports the saved plan as stale and stops; you plan again and review again. Plain `terraform apply` makes a new plan, which may differ from the one people looked at. Note that the plan file can contain sensitive values, so CI keeps it private.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_121') AND order_index = 3)
    RETURNING id
)
