       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_132'), 2, 'Look at the arguments of the `s3` backend (`bucket`, `region`, `encrypt`, `use_lockfile`), what `-backend-config` adds at init time, and `required_version` in the `terraform` block.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_132'), 3, 'A team on Google Cloud keeps its state like this: `terraform { required_version = ">= 1.9.0, < 2.0.0"  backend "gcs" { bucket = "acme-tf-state" } }`, and runs `terraform init -backend-config="prefix=staging"`; the gcs backend locks on its own.');
