-- challenge chal_coding_tf_142 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_tf_142', (SELECT id FROM catalog.course WHERE public_id = 'terraform-infra-as-code'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'terraform-infra-as-code') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-tf-2-2' AND is_deleted = false LIMIT 1), 'static-site-module', 'Write the static-site module', 'Rice Rocket''s web and admin site buckets were two copy-pasted blocks of resources, and the first module that replaced them took `options` as `type = any`: a typo in one key silently left a bucket without its public access block. The editor holds `modules/static-site/main.tf` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: `name` accepts only 1-20 lowercase characters without spaces (error `name must be 1-20 lowercase characters without spaces.`); `options` is a typed object whose `versioning` and `block_public_access` default to `true`, so a call that sets nothing gets the safe settings and a call with a wrong type fails; the bucket is `rice-rocket-<env>-<name>` with the caller''s tags plus `Site`; the public access block and versioning exist only when their option is on; the module configures no provider; and the outputs are the bucket name and ARN as plain values. Run plans a root module that calls yours for the web and admin sites.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
