VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_142'), 'Web and admin calls plan a bucket, a public access block and versioning each', '{"checks":["parse","plan","actions"],"env":"staging","calls":{"web":{"name":"web","options":{"versioning":true}},"admin":{"name":"admin","options":{}}}}', '{"parse":"ok","plan":"Plan: 6 to add, 0 to change, 0 to destroy.","actions":{"module.admin.aws_s3_bucket.this":"create","module.admin.aws_s3_bucket_public_access_block.this[0]":"create","module.admin.aws_s3_bucket_versioning.this[0]":"create","module.web.aws_s3_bucket.this":"create","module.web.aws_s3_bucket_public_access_block.this[0]":"create","module.web.aws_s3_bucket_versioning.this[0]":"create"}}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_142'), 'Buckets are named per environment and site; outputs are the name and the ARN', '{"checks":["names","outputs"],"env":"staging","calls":{"web":{"name":"web","options":{"versioning":true}},"admin":{"name":"admin","options":{}}}}', '{"names":{"module.web.aws_s3_bucket.this":"rice-rocket-staging-web","module.admin.aws_s3_bucket.this":"rice-rocket-staging-admin"},"outputs":{"web_bucket":"rice-rocket-staging-web","web_bucket_arn":"(known after apply)","admin_bucket":"rice-rocket-staging-admin","admin_bucket_arn":"(known after apply)"}}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_142'), 'The module takes env, name, options and tags, and configures no provider', '{"checks":["inputs","providers"],"env":"staging","calls":{"web":{"name":"web","options":{"versioning":true}},"admin":{"name":"admin","options":{}}}}', '{"inputs":["env","name","options","tags"],"providers":[]}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_142'), 'A call with a wrong option type fails the plan instead of building a bucket', '{"checks":["plan"],"env":"production","calls":{"web":{"name":"web","options":{"versioning":"yes"}}}}', '{"plan":"Error: Invalid value for variable: var.options.versioning: bool required, got string"}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_142'), 'A name with capitals or spaces is refused by the module''s validation', '{"checks":["plan"],"env":"production","calls":{"admin":{"name":"Admin Site"}}}', '{"plan":"Error: Invalid value for variable: var.name: name must be 1-20 lowercase characters without spaces."}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_142'), 'Opting out of versioning drops only the versioning resource of that site', '{"checks":["plan","actions"],"env":"production","calls":{"web":{"name":"web","options":{"versioning":false}},"admin":{"name":"admin"}}}', '{"plan":"Plan: 5 to add, 0 to change, 0 to destroy.","actions":{"module.admin.aws_s3_bucket.this":"create","module.admin.aws_s3_bucket_public_access_block.this[0]":"create","module.admin.aws_s3_bucket_versioning.this[0]":"create","module.web.aws_s3_bucket.this":"create","module.web.aws_s3_bucket_public_access_block.this[0]":"create"}}', 5, false, true, 6);
