INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151'), 1, 'Separate the two things a refresh can change: the state file, and the real objects in AWS. Which one does `-refresh-only` write to?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151'), 2, 'An import adopts an existing object into state. Where does the `resource` block that describes it come from, and what can `-generate-config-out` do about it?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151'), 3, 'A `moved` block is applied per state. Count the states that still record the old addresses before deleting one.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151'), 'Someone raised the api log retention in the AWS console. The team ran:

```text
$ terraform plan -refresh-only -var env=production
Note: Objects have changed outside of Terraform

  # aws_cloudwatch_log_group.api has changed
  ~ resource "aws_cloudwatch_log_group" "api" {
      ~ retention_in_days = 30 -> 90
    }

Would you like to update the Terraform state to reflect these detected changes?
```

Statement: "Running `terraform apply -refresh-only` now sets the log group back to 30 days, because the configuration still says 30."', 'single_choice'::question_type, 'False. A refresh-only apply changes nothing in AWS: it only records the real values (90 days) in the state. The configuration still says 30, so the next normal plan proposes `90 -> 30`. The team has to decide: write `retention_in_days = 90` into the code to adopt the console change, or let a normal apply revert it. The misconception is that refresh-only enforces the configuration; it does the opposite.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151'), 'The worker log group was created by hand. The team added only this and planned:

```hcl
import {
  to = aws_cloudwatch_log_group.worker
  id = "/rice-rocket-production/worker"
}
```

```text
$ terraform plan
Error: Configuration for import target does not exist
```

Statement: "An import block writes the matching `resource` block into the configuration by itself, so this error means the id is wrong."', 'single_choice'::question_type, 'False. The import block says which existing object to adopt and at which address, but the `resource "aws_cloudwatch_log_group" "worker"` block at that address must exist in the configuration. `terraform plan -generate-config-out=generated.tf` can draft it from the real object for you to review and move into place. The id is fine here; the target is missing. The misconception is that importing writes code automatically.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151'), 'The refactor replaced `aws_s3_bucket.web` and `aws_s3_bucket.admin` with one `for_each` resource and two `moved` blocks. Production applied it last week; staging has not been planned since. A cleanup pull request deletes the moved blocks:

```text
$ terraform plan -var env=staging
  # aws_s3_bucket.admin will be destroyed
  # aws_s3_bucket.web will be destroyed
  # aws_s3_bucket.site["admin"] will be created
  # aws_s3_bucket.site["web"] will be created
Plan: 2 to add, 0 to change, 2 to destroy.
```

Statement: "Moved blocks must stay until every state that still has the old addresses has been applied with them; removed too early, the staging plan destroys and recreates both buckets."', 'single_choice'::question_type, 'True. A `moved` block rewrites addresses in the state that is being planned. Production''s state already has `site["web"]`, but staging''s still has `aws_s3_bucket.web`, and without the block Terraform sees one object to delete and another to create. Keep moved blocks for as long as any environment, or any other team using the module, may still hold the old addresses; they cost nothing once applied.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_tf_151') AND order_index = 3)
    RETURNING id
)
