INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 1, 'For every object in the plan, ask what Terraform knows about it: is its new address in the state, is there a `moved` block from its old one, or is it a real object that no state knows yet?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 2, 'Look at `moved { from = ...  to = ... }` with the exact for_each key, `import { to = ...  id = ... }` with the id format the resource type documents, and which value the configuration must hold so that the plan does not undo the console change.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 3, 'Turning two IAM roles into one `aws_iam_role.svc` with `for_each = toset(["api", "worker"])` keeps them with `moved { from = aws_iam_role.api  to = aws_iam_role.svc["api"] }` (and one for worker); a role made by hand is adopted with `import { to = aws_iam_role.ci  id = "rice-rocket-ci" }` (the role name is its id).');
