VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 'The production plan imports one log group and adds, changes and destroys nothing', '{"checks":["parse","plan","destroyed"],"env":"production","state":{"aws_s3_bucket.web":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-production-web","id":"rice-rocket-production-web","arn":"arn:aws:s3:::rice-rocket-production-web"}},"aws_s3_bucket.admin":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-production-admin","id":"rice-rocket-production-admin","arn":"arn:aws:s3:::rice-rocket-production-admin"}},"aws_cloudwatch_log_group.api":{"type":"aws_cloudwatch_log_group","attrs":{"name":"/rice-rocket-production/api","retention_in_days":30,"id":"/rice-rocket-production/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/api"}}},"remote":{"aws_cloudwatch_log_group.api":{"name":"/rice-rocket-production/api","retention_in_days":90,"id":"/rice-rocket-production/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/api"}},"importable":{"/rice-rocket-production/worker":{"name":"/rice-rocket-production/worker","retention_in_days":14,"id":"/rice-rocket-production/worker","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/worker"}}}', '{"parse":"ok","plan":"Plan: 1 to import, 0 to add, 0 to change, 0 to destroy.","destroyed":[]}', 6, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 'Both buckets move to their for_each keys and the worker log group is imported', '{"checks":["actions"],"env":"production","state":{"aws_s3_bucket.web":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-production-web","id":"rice-rocket-production-web","arn":"arn:aws:s3:::rice-rocket-production-web"}},"aws_s3_bucket.admin":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-production-admin","id":"rice-rocket-production-admin","arn":"arn:aws:s3:::rice-rocket-production-admin"}},"aws_cloudwatch_log_group.api":{"type":"aws_cloudwatch_log_group","attrs":{"name":"/rice-rocket-production/api","retention_in_days":30,"id":"/rice-rocket-production/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/api"}}},"remote":{"aws_cloudwatch_log_group.api":{"name":"/rice-rocket-production/api","retention_in_days":90,"id":"/rice-rocket-production/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/api"}},"importable":{"/rice-rocket-production/worker":{"name":"/rice-rocket-production/worker","retention_in_days":14,"id":"/rice-rocket-production/worker","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/worker"}}}', '{"actions":{"aws_cloudwatch_log_group.api":"no-op","aws_cloudwatch_log_group.worker":"import","aws_s3_bucket.site[\"admin\"]":"moved from aws_s3_bucket.admin","aws_s3_bucket.site[\"web\"]":"moved from aws_s3_bucket.web"}}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 'The api keeps the 90 days set in the console; the worker keeps its 14', '{"checks":["retention"],"env":"production","state":{"aws_s3_bucket.web":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-production-web","id":"rice-rocket-production-web","arn":"arn:aws:s3:::rice-rocket-production-web"}},"aws_s3_bucket.admin":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-production-admin","id":"rice-rocket-production-admin","arn":"arn:aws:s3:::rice-rocket-production-admin"}},"aws_cloudwatch_log_group.api":{"type":"aws_cloudwatch_log_group","attrs":{"name":"/rice-rocket-production/api","retention_in_days":30,"id":"/rice-rocket-production/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/api"}}},"remote":{"aws_cloudwatch_log_group.api":{"name":"/rice-rocket-production/api","retention_in_days":90,"id":"/rice-rocket-production/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/api"}},"importable":{"/rice-rocket-production/worker":{"name":"/rice-rocket-production/worker","retention_in_days":14,"id":"/rice-rocket-production/worker","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-production/worker"}}}', '{"retention":{"api":90,"worker":14}}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_tf_152'), 'Staging, with its own state and hand-made log group, also plans without loss', '{"checks":["plan","destroyed"],"env":"staging","state":{"aws_s3_bucket.web":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-staging-web","id":"rice-rocket-staging-web","arn":"arn:aws:s3:::rice-rocket-staging-web"}},"aws_s3_bucket.admin":{"type":"aws_s3_bucket","attrs":{"bucket":"rice-rocket-staging-admin","id":"rice-rocket-staging-admin","arn":"arn:aws:s3:::rice-rocket-staging-admin"}},"aws_cloudwatch_log_group.api":{"type":"aws_cloudwatch_log_group","attrs":{"name":"/rice-rocket-staging/api","retention_in_days":30,"id":"/rice-rocket-staging/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-staging/api"}}},"remote":{"aws_cloudwatch_log_group.api":{"name":"/rice-rocket-staging/api","retention_in_days":90,"id":"/rice-rocket-staging/api","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-staging/api"}},"importable":{"/rice-rocket-staging/worker":{"name":"/rice-rocket-staging/worker","retention_in_days":14,"id":"/rice-rocket-staging/worker","arn":"arn:aws:logs:ap-southeast-1:123456789012:log-group:/rice-rocket-staging/worker"}}}', '{"plan":"Plan: 1 to import, 0 to add, 0 to change, 0 to destroy.","destroyed":[]}', 6, false, true, 4),
