-- challenge chal_coding_tf_162 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_tf_162', (SELECT id FROM catalog.course WHERE public_id = 'terraform-infra-as-code'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'terraform-infra-as-code') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-tf-3-2' AND is_deleted = false LIMIT 1), 'one-root-module-per-environment', 'One configuration for staging and production', 'Rice Rocket''s `infra/staging/` and `infra/production/` folders started as copies and drifted apart, and the attempt to merge them with `terraform.workspace` conditionals once applied staging values to production. The editor holds the single `infra/main.tf` that replaces both, with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: `env` accepts only `staging` or `production` (error message `env must be staging or production.`); every difference between the environments (database size, backup retention, deletion protection, log retention) lives in one settings map and is read through one lookup by `var.env`, never through the CLI workspace (CI always plans in the `default` workspace); the database `rice-rocket-<env>` takes its size and protection from that lookup; and `api`, `courier-matcher` and `notifications` each get a log group `/rice-rocket-<env>/<service>` addressed by the service name. Run plans the file for both environments, in different workspaces, and against production''s current state.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
